INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE code = 'DO';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & validation statuses', '[["Invoice format", "XML, per DGII''s own e-CF technical report"], ["Validation statuses", "aceptado / aceptado condicional / rechazado / en proceso, returned with a TrackID"], ["Legal effect", "Only a DGII-accepted e-CF supports the buyer''s commercial approval or tax deduction"], ["Digital signature", "Certificate from an INDOTEL-accredited provider, per Ley 126-02"]]', 'One vendor source (EDICOM) describes the XML as UBL-based; DGII''s own technical report does not itself name UBL as the base standard -- treat the UBL claim as plausible but vendor-sourced only, not DGII-confirmed.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE code = 'DO';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'From pilot to mandate', '[["2018", "DGII announces a pilot for early 2019"], ["2019", "Voluntary pilot runs (10 companies enrolled, 7 completed certification)"], ["Jan 2020", "Norma General 01-2020 formalizes a voluntary authorization regime"], ["May 2023", "Ley 32-23 makes e-CF mandatory on a phased timeline"], ["Oct 2024", "Decreto 587-24 implements Ley 32-23''s operational rules (exact day disputed across sources -- see below)"]]', 'Three independent secondary sources give three different dates for Decreto 587-24 (10, 14, and 15 October 2024); this page cites October 2024 without a specific day pending direct confirmation from DGII''s own PDF, which could not be machine-read in this research round.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE code = 'DO';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Rollout by DGII taxpayer category', '[["Grandes Contribuyentes Nacionales", "Mandatory from 15 May 2024 -- exclusive e-CF (paper retired) from 1 Jan 2026 per Aviso 25-25"], ["Grandes Contribuyentes Locales y Medianos", "Mandatory from 15 Nov 2025 (extended 6 months from the original 15 May 2025 deadline by Aviso 12-25)"], ["Pequeños, Micros y No Clasificados", "Mandatory from 15 Nov 2026 (extended 6 months from the original 15 May 2026 deadline by Aviso 06-26) -- the current final wave"], ["Government/state entities", "Follow the same wave structure as their private-sector size-equivalent"]]', 'No revenue-threshold figures in Dominican pesos were found publicly defining these DGII taxpayer-size categories -- they reflect DGII''s own internal administrative classification, frozen as of Ley 32-23''s 16 May 2023 effective date.', NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 1, 'pills' FROM countries WHERE code = 'DO';
