INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE code = 'DO';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚠️ Tax infractions (Ley 32-23, Art. 26-29)', NULL, NULL, 'Article 26 lists 16 tax infractions -- failing to issue an e-CF when obligated, issuing without DGII authorization, a missing or invalid digital certificate, using an unauthorized certificate provider, post-signature alteration, non-standard XML, failure to retain printed representations, and late transmission, among others. Infractions 1-15 are sanctioned per Código Tributario (Ley 11-92) Art. 257 -- fines of 5 to 30 minimum salaries, plus possible accessory sanctions (suspension of concessions/privileges, closure). Late-submission infractions are sanctioned separately under Código Tributario Art. 205(3). No fixed peso amounts are given in the law itself -- all figures are expressed as multiples of the minimum salary.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE code = 'DO';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚖️ Criminal offenses (Ley 32-23, Art. 30-31)', NULL, NULL, 'Article 30 (fraudulent e-CF) carries 1 to 5 years'' imprisonment plus a fine of 2x to 4x the invoice value, and possible permanent business closure. Article 31 (hacking, unauthorized system access, or data alteration) carries 5 to 10 years'' imprisonment plus a fine of 100 to 400 minimum public-sector salaries. Both figures are sourced directly from DGII''s own hosted PDF of Ley 32-23.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE code = 'DO';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔍 What we could not confirm', NULL, NULL, 'Three items are flagged from this research round rather than presented as settled fact: (1) Decreto 587-24''s exact calendar day -- three independent secondary sources disagree (10, 14, or 15 October 2024), and DGII''s own PDF could not be machine-read in this session; (2) the 2019 pilot''s exact statistics (10 companies enrolled, 7 completed, ~723,000 e-CF issued), traced only to a single Dominican newspaper rather than a DGII primary source; (3) whether e-CF''s XML schema is genuinely UBL-based, a claim sourced only from a compliance vendor (EDICOM), not DGII''s own technical documentation.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE code = 'DO';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your DGII taxpayer-size category and applicable deadline', 'Your Art. 37 compliance deadline depends entirely on whether DGII classifies you as Gran Contribuyente Nacional, Gran Contribuyente Local, Mediano, Pequeño, Micro, or No Clasificado -- check your classification directly with DGII if unsure.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE code = 'DO';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Large National, Local, or Medium Taxpayers: confirm e-CF certification is already complete', 'These categories'' deadlines (15 May 2024 and 15 November 2025) have already passed -- if not yet certified, this is a live compliance gap, not a future planning item.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE code = 'DO';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Small, Micro, and previously-Unclassified taxpayers: prepare ahead of 15 November 2026', 'Register for DGII''s free Facturador Gratuito tool (capped at 150 invoices/month, DGII-adjustable) or select a certified paid solution well before the deadline -- DGII reports rapid adoption growth in this segment already.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE code = 'DO';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Large National Taxpayers: confirm no invoicing workflow still relies on paper vouchers', 'From 1 January 2026, this segment may issue e-CF exclusively -- paper Type B vouchers no longer apply, per Aviso 25-25.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE code = 'DO';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Obtain a digital certificate from an INDOTEL-accredited provider', 'Digital signing of your e-CF requires a certificate from a provider accredited under Ley 126-02 -- confirm your provider''s accreditation status before relying on it.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE code = 'DO';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Check DGII''s avisosInformativos index for further deadline extensions', 'Both later waves (Large Local & Medium, and Small/Micro/Unclassified) have already received 6-month extensions via DGII avisos -- confirm the current status of your wave''s deadline rather than assuming Ley 32-23''s original dates still apply.');
